// Persistent extraction state: per-session watermarks and the auto-dream gate.
// <CLAUDE_CONFIG_DIR>/opencode-memory/<sanitizePath(canonicalRoot)>/extraction-state.json
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, unlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { withFileLock } from "../util/exclusiveFile.js";
export const EXTRACTION_STATE_VERSION = 1;
export const EXTRACTION_STATE_FILE = "extraction-state.json";
export const MAINTENANCE_LOCK_FILE = "maintenance.lock";
export const STATE_LOCK_FILE = "extraction-state.lock";
export const SESSION_STATE_TTL_MS = 30 * 24 * 60 * 60 * 1000;
export function emptyExtractionState() {
    return { version: EXTRACTION_STATE_VERSION, sessions: {}, autodream: { lastConsolidatedAt: 0, sessionsSince: [] } };
}
function isRecord(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}
function normaliseSession(value) {
    if (!isRecord(value))
        return undefined;
    const updatedAt = typeof value.updatedAt === "number" && Number.isFinite(value.updatedAt) ? value.updatedAt : 0;
    const failures = typeof value.failures === "number" && Number.isFinite(value.failures) ? value.failures : 0;
    const state = { updatedAt, failures };
    if (typeof value.lastExtractedMessageID === "string")
        state.lastExtractedMessageID = value.lastExtractedMessageID;
    if (typeof value.lastMessageAt === "number" && Number.isFinite(value.lastMessageAt))
        state.lastMessageAt = value.lastMessageAt;
    if (typeof value.attemptedAt === "number" && Number.isFinite(value.attemptedAt))
        state.attemptedAt = value.attemptedAt;
    return state;
}
// Tolerant parser: a missing or corrupt file yields empty state instead of disabling extraction.
export function parseExtractionState(raw) {
    const data = emptyExtractionState();
    let parsed;
    try {
        parsed = JSON.parse(raw);
    }
    catch {
        return data;
    }
    if (!isRecord(parsed))
        return data;
    if (isRecord(parsed.sessions)) {
        for (const [id, value] of Object.entries(parsed.sessions)) {
            const session = normaliseSession(value);
            if (session)
                data.sessions[id] = session;
        }
    }
    if (isRecord(parsed.autodream)) {
        const last = parsed.autodream.lastConsolidatedAt;
        if (typeof last === "number" && Number.isFinite(last))
            data.autodream.lastConsolidatedAt = last;
        if (Array.isArray(parsed.autodream.sessionsSince)) {
            data.autodream.sessionsSince = parsed.autodream.sessionsSince.filter((s) => typeof s === "string");
        }
    }
    return data;
}
// Never cached: several OpenCode processes may maintain the same project (#30). Every `update()` is a
// read-modify-write under a short cross-process file lock, so two processes committing different
// sessions at the same time cannot overwrite each other. The file is tiny and writes are rare.
export class ExtractionStateStore {
    stateDir;
    now;
    filePath;
    lockPath;
    stateLockPath;
    constructor(stateDir, now = Date.now) {
        this.stateDir = stateDir;
        this.now = now;
        this.filePath = join(stateDir, EXTRACTION_STATE_FILE);
        this.lockPath = join(stateDir, MAINTENANCE_LOCK_FILE);
        this.stateLockPath = join(stateDir, STATE_LOCK_FILE);
    }
    read() {
        let raw = "";
        try {
            raw = readFileSync(this.filePath, "utf-8");
        }
        catch {
            // first run
        }
        return parseExtractionState(raw);
    }
    getSession(sessionID) {
        return this.read().sessions[sessionID];
    }
    // `mutate` sees the on-disk state as of this moment (under the lock), so it can make decisions
    // against what other processes committed, not against a snapshot taken earlier.
    update(mutate) {
        mkdirSync(this.stateDir, { recursive: true });
        return withFileLock(this.stateLockPath, () => {
            const data = this.read();
            mutate(data);
            this.prune(data);
            this.write(data);
            return data;
        });
    }
    prune(data) {
        const cutoff = this.now() - SESSION_STATE_TTL_MS;
        for (const [id, session] of Object.entries(data.sessions)) {
            if (Math.max(session.updatedAt, session.attemptedAt ?? 0) < cutoff)
                delete data.sessions[id];
        }
    }
    write(data) {
        mkdirSync(this.stateDir, { recursive: true });
        const tmp = `${this.filePath}.${process.pid}.tmp`;
        writeFileSync(tmp, `${JSON.stringify(data, null, 2)}\n`, "utf-8");
        renameSync(tmp, this.filePath);
    }
}
// POSIX `cksum` (CRC-32/CKSUM: polynomial 0x04C11DB7, non-reflected, length appended, inverted).
// v1's bash wrapper keyed its auto-dream lock file on `cksum` of the git top-level path.
export function posixCksum(input) {
    const bytes = Buffer.from(input, "utf-8");
    let crc = 0;
    const feed = (byte) => {
        crc ^= byte << 24;
        for (let i = 0; i < 8; i++) {
            crc = crc & 0x80000000 ? ((crc << 1) ^ 0x04c11db7) >>> 0 : (crc << 1) >>> 0;
        }
    };
    for (const byte of bytes)
        feed(byte);
    let length = bytes.length;
    while (length > 0) {
        feed(length & 0xff);
        length >>>= 8;
    }
    return (~crc >>> 0) >>> 0;
}
// v1 stored the last successful consolidation time as the mtime of
// <CLAUDE_CONFIG_DIR>/opencode-memory/<cksum(project root)>.consolidate-lock. Carry it over once so
// upgrading does not immediately trigger a consolidation pass, then remove the old file.
export function migrateLegacyAutodreamState(store, legacyDir, projectRoots) {
    if (store.read().autodream.lastConsolidatedAt > 0)
        return false;
    let migrated = false;
    for (const root of new Set(projectRoots)) {
        const legacyPath = join(legacyDir, `${posixCksum(root)}.consolidate-lock`);
        if (!existsSync(legacyPath))
            continue;
        try {
            const mtimeMs = statSync(legacyPath).mtimeMs;
            store.update((data) => {
                data.autodream.lastConsolidatedAt = Math.max(data.autodream.lastConsolidatedAt, Math.floor(mtimeMs));
            });
            unlinkSync(legacyPath);
            migrated = true;
        }
        catch {
            // best-effort
        }
    }
    return migrated;
}
